};


/**
 * @method
 * @name scwin.onCompleteResponse
 * @author Inswave
 * @date 2026. 09. 29
 * @param responseXML
 * @returns
 * @hidden N
*/
scwin.onCompleteResponse = async function (responseXML) {
    /* sdd-asis-lifecycle:begin onCompleteResponse — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ((responseXML == null) || ('' === responseXML)) {
        await $c.win.alert("데이터를 불러올 수 없습니다.");
    } else {
        const frm = (document.smsSendForm || { elements: [] });
        const xmlDoc = xmlHttp.responseXML;
        const chkSubstituteInfo = xmlDoc.getElementsByTagName("chkSubstituteInfo")[0];
        let chrgWorkYn = "";
        const chrgNm = "";
        const toDate = "";
        const substituteInfo = "";
        if (chkSubstituteInfo != null) {
            chrgWorkYn = chkSubstituteInfo.getElementsByTagName("result")[0].firstChild.nodeValue;
        }
        if (chrgWorkYn === 'N') {
            $("input:radio[name='empNm']").eq(0).attr("checked", "false");
            $("input:radio[name='empNm']").eq(0).attr("disabled", "true");
            $("input:radio[name='empNm']").eq(1).attr("checked", "false");
        } else {
            $("input:radio[name='empNm']").eq(0).attr("checked", "true");
            (($c.util.getComponent('slc_empNm2')) && ($c.util.getComponent('slc_empNm2')).setDisabled ? ($c.util.getComponent('slc_empNm2')).setDisabled((("true") === '' || ("true") === false || ("true") === 'false') ? false : ((("true") === true || ("true") === 'true' || ("true") === 'disabled') ? true : ("true"))) : void 0);
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
