 * @name scwin.fnRcvrEmpChk
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnRcvrEmpChk = function () {
    /* sdd-asis-lifecycle:begin fnRcvrEmpChk — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const rcvrEmp = $("input:radio[name='empNm']");
    if (rcvrEmp.eq(0).is(':checked')) {
        (($c.util.getComponent('slc_empNm2')) && ($c.util.getComponent('slc_empNm2')).setDisabled ? ($c.util.getComponent('slc_empNm2')).setDisabled((("true") === '' || ("true") === false || ("true") === 'false') ? false : ((("true") === true || ("true") === 'true' || ("true") === 'disabled') ? true : ("true"))) : void 0);
    } else {
        $("select[name='empNm2']").removeAttr('disabled');
    }
    /* sdd-asis-lifecycle:end */
};
